(() => {
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
  let lang=new URLSearchParams(location.search).get('lang')==='en'?'en':'es',step=0,room='overview',selected=null,engine=null;
  const feed=$('#demo-data')?JSON.parse($('#demo-data').textContent):null,p=feed?.project;
  const L=(es,en)=>lang==='es'?es:en;
  const copy=[['01 / LA ARQUITECTURA','01 / THE ARCHITECTURE','La primera mirada.','The first look.','Acércate a las terrazas, gira el edificio y descubre sus detalles. La visita continúa con la elección de tu hogar.','Move closer to the terraces, rotate the building and discover its details. Continue by choosing your home.'],['02 / TU DEPARTAMENTO','02 / YOUR APARTMENT','Un espacio para ti.','A space for you.','Elige un piso y compara los hogares. También puedes tocar una unidad en el edificio.','Choose a floor and compare homes. You can also tap a unit on the building.'],['03 / LA VIDA DENTRO','03 / LIFE INSIDE','Imagina lo cotidiano.','Imagine the everyday.','De la sala a la terraza. Explora materiales, mobiliario y luz en un interior 3D navegable.','From living room to terrace. Explore materials, furnishings and light in a navigable 3D interior.'],['04 / EL SIGUIENTE PASO','04 / YOUR NEXT STEP','Hablemos de tu hogar.','Let’s talk about your home.','Tu selección acompaña la conversación. Una experiencia conectada de principio a fin.','Your selection travels with the conversation. A connected experience from start to finish.']];
  function translate(){document.documentElement.lang=lang;$$('[data-es][data-en]').forEach(e=>e.innerHTML=e.dataset[lang]);$('#language').textContent=lang==='es'?'EN':'ES';$$('a[href^="/"]').forEach(a=>{const url=new URL(a.getAttribute('href'),location.origin);url.searchParams.set('lang',lang);a.setAttribute('href',url.pathname+url.search+url.hash)});if(p){renderStep();list();selection();}document.dispatchEvent(new Event('demo:language'));if($('#architecture'))$('#architecture').setAttribute('aria-label',L('Modelo arquitectónico 3D. Arrastra para girar, usa las flechas o los botones de zoom.','3D architectural model. Drag to rotate, use arrow keys or zoom buttons.'));}
  $('#language').onclick=()=>{lang=lang==='es'?'en':'es';const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState(null,'',url);translate()};
  function renderStep(){const c=copy[step],offset=lang==='es'?0:1;$('#step-label').textContent=c[offset];$('#step-title').textContent=c[2+offset];$('#step-copy').textContent=c[4+offset];$$('[data-step]').forEach(b=>b.setAttribute('aria-current',String(+b.dataset.step===step)));['building','unit','interior','contact'].forEach((key,i)=>$(`#${key}-options`).hidden=i!==step);$('#previous').disabled=step===0;$('#next').hidden=step===3;$('#scene-name').textContent=step===2?L('INTERIOR CONCEPTUAL','CONCEPT INTERIOR'):'RESIDENCIA 01';$$('[data-room]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.room===room)));}
  function showScene(){if(matchMedia('(max-width:700px)').matches)$('#scene-wrap').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});}
  function go(index){step=Math.max(0,Math.min(3,index));renderStep();if(engine){engine.setMode(step===2?'interior':'building',room);if(selected&&step!==2)engine.select(selected.id);}}
  function list(){const floor=+$('#floor').value,beds=$('#bedrooms').value,available=$('#available').checked;const units=p.units.filter(u=>u.floor===floor&&(beds==='all'||feed.typologies[u.type].beds===+beds)&&(!available||u.status==='disponible'));$('#unit-list').innerHTML=units.length?units.map(u=>`<button data-unit="${u.id}" aria-pressed="${selected?.id===u.id}"><div><b>${L('Unidad','Unit')} ${u.id}</b><span>${feed.typologies[u.type].name[lang==='es'?0:1]} · ${L({disponible:'Disponible',reservado:'Reservado',vendido:'Vendido'}[u.status],{disponible:'Available',reservado:'Reserved',vendido:'Sold'}[u.status])}</span></div><b>${u.m2} m²</b></button>`).join(''):`<p class="empty">${L('No hay viviendas que coincidan. Prueba otro piso o filtro.','No matching homes. Try another floor or filter.')}</p>`;$$('[data-unit]').forEach(b=>b.onclick=()=>choose(b.dataset.unit));}
  function choose(id){const unit=p.units.find(u=>u.id===id);if(!unit)return;selected=unit;$('#floor').value=String(unit.floor);if(!$('#unit-options').hidden){$('#bedrooms').value='all';if(unit.status!=='disponible')$('#available').checked=false;}list();selection();engine?.select(id);}
  function selection(){const e=$('#selected-home');if(!selected){e.innerHTML='';$('#enquire').textContent=L('Elegir un departamento →','Choose an apartment →');$('#enquire').href='#main';$('#enquire').onclick=ev=>{ev.preventDefault();go(1)};return;}const u=selected,status=L({disponible:'Disponible',reservado:'Reservado',vendido:'Vendido'}[u.status],{disponible:'Available',reservado:'Reserved',vendido:'Sold'}[u.status]);e.innerHTML=`<b>${p.name} · ${L('Unidad','Unit')} ${u.id}</b><span>${L('Piso','Floor')} ${u.floor} · ${u.m2} m² · ${status}</span>`;const a=$('#enquire');a.textContent=L('Preparar mi consulta ↗','Prepare my enquiry ↗');a.onclick=null;const subject=L(`Consulta demo · Residencia 01 · Unidad ${u.id}`,`Demo enquiry · Residencia 01 · Unit ${u.id}`);const body=L(`Hola, me interesa conocer esta experiencia para mi proyecto. En la demo seleccioné la unidad ${u.id}, piso ${u.floor}, ${feed.typologies[u.type].name[0]}, ${u.m2} m² (${status}).\n\nMi proyecto:\nCiudad:\nDatos de contacto:\n\nReferencia: https://inmobiliaria.alvaropaz.com/proyecto/\nProyecto y disponibilidad de ejemplo.`,`Hello, I would like this experience for my project. In the demo I selected unit ${u.id}, floor ${u.floor}, ${feed.typologies[u.type].name[1]}, ${u.m2} m² (${status}).\n\nMy project:\nCity:\nContact details:\n\nReference: https://inmobiliaria.alvaropaz.com/proyecto/\nSample project and availability.`);a.href=`mailto:alvaroipazr@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;}
  if(p){$('#floor').innerHTML=Array.from({length:p.floors},(_,i)=>`<option value="${i+2}">${i+2}</option>`).join('');$('#floor').value='7';['floor','bedrooms','available'].forEach(id=>$('#'+id).onchange=list);$$('[data-step]').forEach(b=>b.onclick=()=>{go(+b.dataset.step);showScene()});$('#next').onclick=()=>{go(step+1);showScene()};$('#previous').onclick=()=>{go(step-1);showScene()};$$('[data-room]').forEach(b=>b.onclick=()=>{room=b.dataset.room;engine?.setMode('interior',room);renderStep();showScene()});}
  translate();
  const canvas=$('#architecture');if(!canvas)return;
  $$('[data-light]').forEach(b=>b.onclick=()=>{engine?.lighting(+b.dataset.light);$$('[data-light]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});
  $$('[data-camera]').forEach(b=>b.onclick=()=>engine?.command(b.dataset.camera));
  function fallback(){const status=$('#scene-status');status.hidden=false;status.textContent=L('La vista 3D no está disponible en este navegador. Puedes continuar con el selector de viviendas y preparar tu consulta.','The 3D view is unavailable in this browser. You can continue with home selection and prepare your enquiry.');canvas.dataset.ready='error';}
  canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();fallback()});
  canvas.addEventListener('webglcontextrestored',()=>location.reload());
  AlphaAssets.whenVisible(canvas,()=>AlphaAssets.three().then(()=>{engine=Architecture.create(THREE,canvas,p?id=>{go(1);choose(id)}:null);$('#scene-status').hidden=true;canvas.dataset.ready='true';if(p)go(step);}).catch(fallback));
  window.addEventListener('pagehide',e=>{if(!e.persisted)engine?.dispose()});
})();
